    {
        uxNextRand = ( uxNextRand * ( size_t ) 1103515245 ) + ( size_t ) 12345;
        return ( uxNextRand / ( size_t ) 65536 ) % ( size_t ) 32768;
    }
/*-----------------------------------------------------------*/

    static void prvSRand( size_t uxSeed )
    {
        uxNextRand = uxSeed;
    }

