#include <stdint.h>
#define pdPASS 1
#define pdFALSE 0
#define D 3
static volatile int asserts;
#define configASSERT(x) do{ if(!(x)) asserts++; }while(0)
static int sh(int op, void *arg){ register int r0 __asm__("r0")=op; register void* r1 __asm__("r1")=arg;
 __asm__ volatile("bkpt 0xAB":"+r"(r0):"r"(r1):"memory"); return r0; }
static void puts_(const char*s){ sh(0x04,(void*)s); }
static void putn(long v){ char b[24]; int i=23; b[i]=0; if(!v) b[--i]='0'; while(v){ b[--i]='0'+v%10; v/=10;} puts_(&b[i]); }
__attribute__((noinline)) static int oldf(uint32_t r, uint32_t e){int x=pdPASS;
 if(r>e){configASSERT((r-e)<=D); if((r-e)>D) x=pdFALSE;}
 else{configASSERT((e-r)<=D); if((e-r)>D) x=pdFALSE;} return x;}
__attribute__((noinline)) static int newf(uint32_t r, uint32_t e){int x=pdPASS; uint32_t d;
 if(r>e) d=r-e; else d=e-r; configASSERT(d<=D); if(d>D) x=pdFALSE; return x;}
static const uint32_t bases[]={0,1,2,3,4,5,6,7,100,0x7FFFFFFFu,0x80000000u,0xFFFFFFF0u,0xFFFFFFFCu,0xFFFFFFFFu,0xFFFFFFFEu};
int main(void){
 long n=0,bad=0,p1=0,p2=0;
 for(unsigned b=0;b<sizeof bases/sizeof*bases;b++) for(int de=-20;de<=20;de++) for(int dr=-20;dr<=20;dr++){
  uint32_t e=bases[b]+(uint32_t)de, r=bases[b]+(uint32_t)dr;
  asserts=0; int o=oldf(r,e); int oa=asserts; asserts=0; int nw=newf(r,e); int na=asserts;
  uint64_t ad = r>e ? (uint64_t)r-e : (uint64_t)e-r;
  if(o!=nw||oa!=na) bad++;
  if(ad<=D){ if(nw!=pdPASS||na) bad++; else p1++; } else { if(nw!=pdFALSE||na!=1) bad++; else p2++; }
  n++; }
 puts_("cases="); putn(n); puts_(" P1_ok="); putn(p1); puts_(" P2_ok="); putn(p2); puts_(" mismatches="); putn(bad); puts_("\n");
 static uint32_t ex[2]={0x20026,0}; ex[1]=bad?1:0; sh(0x20,ex); for(;;); }
void Reset(void){ main(); }
__attribute__((section(".vectors"),used)) void (* const vec[])(void) = { (void(*)(void))0x20010000, Reset };
EOF
